/envelope/{envelope_id}/signing_steps.post:
from signplus import Signplus, Environment
from signplus.models import AddEnvelopeSigningStepsRequest

sdk = Signplus(
    access_token="YOUR_ACCESS_TOKEN",
    base_url=Environment.DEFAULT.value,
    timeout=10000
)

request_body = AddEnvelopeSigningStepsRequest(
    signing_steps=[
        {
            "recipients": [
                {
                    "name": "<string>",
                    "email": "<string>",
                    "role": "IN_PERSON_SIGNER",
                    "id_": "<string>",
                    "uid": "<string>",
                    "verification": {
                        "type_": "SMS",
                        "value": "<string>"
                    }
                }
            ]
        }
    ]
)

result = sdk.signing_steps.add_envelope_signing_steps(
    request_body=request_body,
    envelope_id="envelope_id",
    accept="application/json"
)

print(result)

